changeSet.sql:
ALTER TABLE m_savings_rate_batch ADD CONSTRAINT ck_srb_rate_type CHECK (rate_type IN ('FIXED','TIERED','REFERENCE_RATE') AND ((rate_type='REFERENCE_RATE' AND reference_id IS NOT NULL AND benchmark_version IS NOT NULL) OR (rate_type<>'REFERENCE_RATE' AND reference_id IS NULL AND benchmark_version IS NULL)));
ALTER TABLE m_savings_rate_batch ADD CONSTRAINT ck_srb_state CHECK (status IN ('DRAFT','PENDING_AUTHORIZATION','AUTHORIZED','SCHEDULED','ASSESSING','BLOCKED','REJECTED','CANCELLED'));
ALTER TABLE m_savings_rate_batch ADD CONSTRAINT ck_srb_progress CHECK (revision>0 AND discovery_checkpoint>=0 AND cutoff_account_id>=discovery_checkpoint);
ALTER TABLE m_savings_rate_batch ADD CONSTRAINT ck_srb_checker CHECK (checker_id IS NULL OR (checker_id<>maker_id AND checker_id<>submitter_id));
ALTER TABLE m_savings_rate_batch ADD CONSTRAINT ck_srb_authorized CHECK (status NOT IN ('AUTHORIZED','SCHEDULED','ASSESSING','BLOCKED') OR (checker_id IS NOT NULL AND authorized_hash IS NOT NULL AND planning_complete));
ALTER TABLE m_savings_rate_account ADD CONSTRAINT ck_sra_eligibility CHECK (eligibility IN ('ELIGIBLE','BLOCKED','EXCLUDED'));
-- BE-05 has no financial adapter. Even accidental success writes must fail closed.
ALTER TABLE m_savings_rate_account ADD CONSTRAINT ck_sra_outcome CHECK (outcome IN ('PENDING','SKIPPED','BLOCKED','FAILED_RETRYABLE','FAILED_FINAL','UNKNOWN_OUTCOME'));
ALTER TABLE m_savings_rate_account ADD CONSTRAINT ck_sra_attempts CHECK (attempt_count>=0 AND confirmed_operation_id IS NULL);
CREATE FUNCTION savings_rate_append_only() RETURNS trigger AS $$
BEGIN RAISE EXCEPTION 'Rate propagation evidence is append-only'; END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER tr_sraud_immutable BEFORE UPDATE OR DELETE ON m_savings_rate_audit FOR EACH ROW EXECUTE FUNCTION savings_rate_append_only();
CREATE TRIGGER tr_srat_immutable BEFORE UPDATE OR DELETE ON m_savings_rate_attempt FOR EACH ROW EXECUTE FUNCTION savings_rate_append_only();
CREATE FUNCTION savings_rate_batch_guard() RETURNS trigger AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain rate propagation batches'; END IF;
 IF (NEW.id,NEW.tenant_id,NEW.request_key,NEW.savings_product_id,NEW.policy_version,NEW.rate_type,NEW.reference_id,NEW.benchmark_version,NEW.effective_date,NEW.population_cutoff,NEW.population_business_date,NEW.cutoff_account_id,NEW.source_json,NEW.source_hash,NEW.change_classification,NEW.maker_id,NEW.created_at)
 IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.request_key,OLD.savings_product_id,OLD.policy_version,OLD.rate_type,OLD.reference_id,OLD.benchmark_version,OLD.effective_date,OLD.population_cutoff,OLD.population_business_date,OLD.cutoff_account_id,OLD.source_json,OLD.source_hash,OLD.change_classification,OLD.maker_id,OLD.created_at)
 THEN RAISE EXCEPTION 'Rate propagation plan source is immutable'; END IF;
 IF OLD.planning_complete AND (NEW.planning_complete,NEW.discovery_checkpoint,NEW.population_hash) IS DISTINCT FROM (OLD.planning_complete,OLD.discovery_checkpoint,OLD.population_hash)
 THEN RAISE EXCEPTION 'Sealed population is immutable'; END IF;
 IF OLD.authorized_hash IS NOT NULL AND (NEW.authorized_hash,NEW.checker_id,NEW.decided_at,NEW.submitter_id,NEW.submitted_at) IS DISTINCT FROM (OLD.authorized_hash,OLD.checker_id,OLD.decided_at,OLD.submitter_id,OLD.submitted_at)
 THEN RAISE EXCEPTION 'Rate propagation authorization is immutable'; END IF;
 RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER tr_srb_guard BEFORE UPDATE OR DELETE ON m_savings_rate_batch FOR EACH ROW EXECUTE FUNCTION savings_rate_batch_guard();
CREATE FUNCTION savings_rate_account_guard() RETURNS trigger AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retain rate propagation population'; END IF;
 IF TG_OP='INSERT' THEN
   PERFORM id FROM m_savings_rate_batch WHERE id=NEW.batch_id AND status='DRAFT' AND NOT planning_complete FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Population can only expand during draft discovery'; END IF;
 ELSE
   IF (NEW.batch_id,NEW.savings_account_id,NEW.operation_key,NEW.previous_policy_version,NEW.account_snapshot,NEW.eligibility,NEW.eligibility_reason)
   IS DISTINCT FROM (OLD.batch_id,OLD.savings_account_id,OLD.operation_key,OLD.previous_policy_version,OLD.account_snapshot,OLD.eligibility,OLD.eligibility_reason)
   THEN RAISE EXCEPTION 'Rate account snapshot is immutable'; END IF;
 END IF;
 RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER tr_sra_guard BEFORE INSERT OR UPDATE OR DELETE ON m_savings_rate_account FOR EACH ROW EXECUTE FUNCTION savings_rate_account_guard();
